namespace sv_59d45c710f004502b6e26f3df7973ed5.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service — in Blazor Server each circuit gets its own instance,
/// so every user has independent theme state.
/// </summary>
public sealed class ThemeService
{
    private ThemeMode _theme = ThemeMode.System;
    private string _accentColor = "#0d6efd";

    public ThemeMode Theme
    {
        get => _theme;
        set
        {
            if (_theme == value) return;
            _theme = value;
            NotifyChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyChanged();
        }
    }

    public event Action? OnChange;

    private void NotifyChanged() => OnChange?.Invoke();
}

@* Interactive island inside the static layout — subscribes to
   ThemeService so it updates in real-time without page navigation. *@
@rendermode InteractiveServer
@inject ThemeService ThemeService
@implements IDisposable

<span class="theme-indicator" style="color: @ThemeService.AccentColor;"
      title="Current theme">
    @Icon @ThemeService.Theme
</span>

@code {
    private string Icon => ThemeService.Theme switch
    {
        ThemeMode.Dark   => "🌙",
        ThemeMode.Light  => "☀️",
        _                => "💻"
    };

    protected override void OnInitialized()
        => ThemeService.OnChange += HandleThemeChanged;

    private void HandleThemeChanged()
        => InvokeAsync(StateHasChanged);

    public void Dispose()
        => ThemeService.OnChange -= HandleThemeChanged;
}

@page "/settings"
@rendermode InteractiveServer
@inject ThemeService ThemeService
@implements IDisposable

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="mb-3">
    <label class="form-label fw-bold">Theme</label>
    <div class="btn-group d-block" role="group">
        @foreach (var mode in Enum.GetValues<ThemeMode>())
        {
            var isActive = ThemeService.Theme == mode;
            <button class="btn @(isActive ? "btn-primary" : "btn-outline-primary")"
                    @onclick="() => ThemeService.Theme = mode">
                @mode
            </button>
        }
    </div>
</div>

<div class="mb-3">
    <label class="form-label fw-bold" for="accent">Accent Color</label>
    <input id="accent" type="color" class="form-control form-control-color"
           value="@ThemeService.AccentColor"
           @onchange="OnAccentChanged" />
</div>

<div class="card mt-4" style="border-color: @ThemeService.AccentColor;">
    <div class="card-body">
        <p class="mb-0">
            <strong>Preview —</strong>
            Theme: <em>@ThemeService.Theme</em>,
            Accent: <span style="color: @ThemeService.AccentColor;">@ThemeService.AccentColor</span>
        </p>
    </div>
</div>

@code {
    protected override void OnInitialized()
        => ThemeService.OnChange += HandleChanged;

    private void OnAccentChanged(ChangeEventArgs e)
        => ThemeService.AccentColor = e.Value?.ToString() ?? "#0d6efd";

    private void HandleChanged()
        => InvokeAsync(StateHasChanged);

    public void Dispose()
        => ThemeService.OnChange -= HandleChanged;
}

